// A pretend database with a callback API: get(key, cb) and set(key, value, cb)
const store = new Map([['user:1', { id: 1, name: 'Ada' }], ['user:2', { id: 2, name: 'Bob' }]]);

export function get(key, cb) {
  setTimeout(() => {
    if (!store.has(key)) return cb(new Error('not found: ' + key));
    cb(null, structuredClone(store.get(key)));
  }, 1);
}

export function set(key, value, cb) {
  setTimeout(() => {
    store.set(key, structuredClone(value));
    cb(null);
  }, 1);
}

