import { get, set } from './db.js';

export function loadUser(id, cb) {
  get('user:' + id, (err, user) => {
    if (err) return cb(err);
    cb(null, user);
  });
}

export function renameUser(id, name, cb) {
  get('user:' + id, (err, user) => {
    if (err) return cb(err);
    user.name = name;
    set('user:' + id, user, (err2) => {
      if (err2) return cb(err2);
      get('user:' + id, cb);
    });
  });
}

