test('promises', async () => {
  assert.deepEqual(await get('user:2'), { id: 2, name: 'Bob' });
  await set('user:3', { id: 3, name: 'Cy' });
  assert.deepEqual(await get('user:3'), { id: 3, name: 'Cy' });
  await assert.rejects(get('nope'), /not found: nope/);
