test('users', async () => {
  assert.deepEqual(await loadUser(1), { id: 1, name: 'Ada' });
  assert.deepEqual(await renameUser(2, 'Bobby'), { id: 2, name: 'Bobby' });
  assert.deepEqual(await loadUser(2), { id: 2, name: 'Bobby' });
  await assert.rejects(loadUser(99), /not found/);
  await assert.rejects(renameUser(99, 'x'), /not found/);
