  const src = readFileSync(new URL('../users.js', import.meta.url), 'utf8');
  assert.ok(src.includes('await'), 'no await in users.js');
  assert.ok(!src.includes('cb'), 'users.js still takes callbacks');
});

solution.db.js:
// A pretend database: get(key, cb?) and set(key, value, cb?). Without a callback they return promises.
const store = new Map([['user:1', { id: 1, name: 'Ada' }], ['user:2', { id: 2, name: 'Bob' }]]);

function maybe(cb, work) {
  const p = new Promise(work);
  if (!cb) return p;
  p.then((v) => cb(null, v), (e) => cb(e));
}

export function get(key, cb) {
  return maybe(cb, (resolve, reject) => {
    setTimeout(() => {
      if (!store.has(key)) return reject(new Error('not found: ' + key));
      resolve(structuredClone(store.get(key)));
    }, 1);
  });
}

export function set(key, value, cb) {
  return maybe(cb, (resolve) => {
    setTimeout(() => {
      store.set(key, structuredClone(value));
      resolve(undefined);
    }, 1);
  });
}

