import { get, set } from './db.js';

export async function loadUser(id) {
  return get('user:' + id);
}

export async function renameUser(id, name) {
  const user = await get('user:' + id);
  user.name = name;
  await set('user:' + id, user);
  return get('user:' + id);
}
